      "tagText": "आकृत्या मोजणे",
      "question": "<div class=\"flex flex-col items-center justify-center my-3 p-3 bg-red-50/60 rounded-2xl border border-slate-200 shadow-sm max-w-sm mx-auto\">\n  <svg width=\"150\" height=\"150\" viewBox=\"0 0 150 150\" xmlns=\"http://www.w3.org/2000/svg\">\n    <rect x=\"25\" y=\"25\" width=\"100\" height=\"100\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"3\"/>\n    <line x1=\"25\" y1=\"25\" x2=\"125\" y2=\"125\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n    <line x1=\"125\" y1=\"25\" x2=\"25\" y2=\"125\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n    <circle cx=\"75\" cy=\"75\" r=\"4\" fill=\"#991b1b\"/>\n  </svg>\n  <span class=\"mt-2 text-xs font-bold text-slate-700 tracking-wide\">दोन्ही कर्ण असणाऱ्या चौकोनातील एकूण ८ त्रिकोण</span>\n</div>एका चौकोनाच्या दोन्ही कर्णांमुळे एकूण किती त्रिकोण तयार होतात?",
